import{_ as e,a0 as o,w as g,s as d,ao as i,I as a,x as n,a1 as t,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用 CSS 提升你的 HTML 文檔 | LCTT x X-CMD","titleTemplate":false,"description":"使用 CSS 提升你的 HTML 文檔 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 CSS 提升你的 HTML 文檔 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 CSS 提升你的 HTML 文檔 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20220813 Level up your HTML document with CSS","title":"使用 CSS 提升你的 HTML 文檔","tag":"202304","desc":""},"relativePath":"202304/20220813 Level up your HTML document with CSS.md","filePath":"[post].md"}'),c={name:"202304/20220813 Level up your HTML document with CSS.md"};function r(h,s,b,u,m,k){const l=o("Link");return g(),d("div",null,[s[34]||(s[34]=i(`<h1 id="使用-css-提升你的-html-文檔" tabindex="-1">使用 CSS 提升你的 HTML 文檔 <a class="header-anchor" href="#使用-css-提升你的-html-文檔" aria-label="Permalink to “使用 CSS 提升你的 HTML 文檔”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/14/155136ypp8ziciecvunbpl.jpg" alt=""></p><blockquote><p>使用 CSS 讓你的 HTML 項目更具風格。</p></blockquote><p>當你編寫文檔時，無論是為開源項目還是技術寫作項目，你都應該有兩個目標：文檔應該寫得好，同時要易於閲讀。前者通過清晰的寫作技巧和技術編輯來解決。第二個目標可以通過對 HTML 文檔進行一些簡單的更改來解決。</p><p>超文本標記語言（HTML）是互聯網的支柱。自 1994 年“萬維網”問世以來，所有網絡瀏覽器都使用 HTML 來顯示文檔和網站。幾乎與此同時，HTML 一直支持樣式表，它是對 HTML 文檔的一種特殊添加，用於定義文本在屏幕上的呈現方式。</p><p>單純用 HTML 編寫項目文檔也是可以的。然而，純 HTML 樣式可能感覺有點簡陋。因此，嘗試向 HTML 文檔添加一些簡單的樣式，為文檔添加一點活力，並使文檔更清晰、更易於閲讀。</p><h3 id="定義一個-html-文檔" tabindex="-1">定義一個 HTML 文檔 <a class="header-anchor" href="#定義一個-html-文檔" aria-label="Permalink to “定義一個 HTML 文檔”">​</a></h3><p>讓我們從一個純 HTML 文檔開始，探索如何向其添加樣式。一個空的 HTML 文檔在頂部包含 <code>&lt;!DOCTYPE html&gt;</code> 定義，後面跟着一個 <code>&lt;html&gt;</code> 塊來定義文檔本身。 在 <code>&lt;html&gt;</code> 元素中，你還需要加上一個文檔標頭，其中包含有關文檔的元數據，例如標題。文檔正文的內容放在父 <code>&lt;html&gt;</code> 塊內的 <code>&lt;body&gt;</code> 塊中。</p><p>你可以使用以下 HTML 代碼定義一個空白頁面：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;!DOCTYPE html&gt;</span></span>
<span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>  &lt;head&gt;</span></span>
<span class="line"><span>    &lt;title&gt;這是一個新文檔&lt;/title&gt;</span></span>
<span class="line"><span>  &lt;/head&gt;</span></span>
<span class="line"><span>  &lt;body&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div>`,10)),a("p",null,[s[1]||(s[1]=n("在另一篇關於 ",-1)),t(l,{href:"https://opensource.com/article/22/8/writing-project-documentation-html"},{default:p(()=>[...s[0]||(s[0]=[n("用 HTML 編寫項目文檔",-1)])]),_:1}),s[2]||(s[2]=n(" 的文章中，我將一個開源棋盤遊戲的自述文件從純文本更新為 HTML 文檔，並使用一些基本的 HTML 標記，如 ",-1)),s[3]||(s[3]=a("code",null,"<h1>",-1)),s[4]||(s[4]=n(" 和 ",-1)),s[5]||(s[5]=a("code",null,"<h2>",-1)),s[6]||(s[6]=n(" 作為標題和副標題，",-1)),s[7]||(s[7]=a("code",null,"<p>",-1)),s[8]||(s[8]=n(" 用於段落，",-1)),s[9]||(s[9]=a("code",null,"<b>",-1)),s[10]||(s[10]=n(" 和 ",-1)),s[11]||(s[11]=a("code",null,"<i>",-1)),s[12]||(s[12]=n(" 用於粗體和斜體文本。讓我們從那篇文章結束的地方繼續講：",-1))]),s[35]||(s[35]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;!DOCTYPE html&gt;</span></span>
<span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>  &lt;head&gt;</span></span>
<span class="line"><span>    &lt;title&gt;簡易 Senet&lt;/title&gt;</span></span>
<span class="line"><span>  &lt;/head&gt;</span></span>
<span class="line"><span>  &lt;body&gt;</span></span>
<span class="line"><span>    &lt;h1&gt;簡易 Senet&lt;/h1&gt;</span></span>
<span class="line"><span>    &lt;h2&gt;遊戲玩法&lt;/h2&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;p&gt;遊戲會自動為你“投擲”投擲棒，並在屏幕右下角顯示結果。&lt;/p&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;p&gt;如果“投擲”結果為零，你失去本輪機會。&lt;/p&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;p&gt;輪到你的時候，遊戲會自動選擇</span></span>
<span class="line"><span>    你在棋盤上的第一塊棋子。 你不一定</span></span>
<span class="line"><span>    能夠用這個棋子走棋，所以選擇你的棋子</span></span>
<span class="line"><span>    移動，然後按 &lt;i&gt;Space&lt;/i&gt;（或 &lt;i&gt;Enter&lt;/i&gt;）移動</span></span>
<span class="line"><span>    它。 你可以通過幾種不同的方法進行選擇：&lt;/p&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;ul&gt;</span></span>
<span class="line"><span>      &lt;li&gt;&lt;i&gt;向上&lt;/i&gt;/&lt;i&gt;向下&lt;/i&gt;/&lt;i&gt;向左&lt;/i&gt;/&lt;i&gt;向右&lt;/i&gt; to</span></span>
<span class="line"><span>      朝特定方塊移動。&lt;/li&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>      &lt;li&gt;加號 (&lt;b&gt;+&lt;/b&gt;) 或減號 (&lt;b&gt;-&lt;/b&gt;) 使棋子在棋盤上向“左”或向“右”移動。</span></span>
<span class="line"><span>      請注意，它們會自動遵循棋盤的“倒過來的 S”方向移動。&lt;/li&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>      &lt;li&gt;&lt;em&gt;Tab&lt;/em&gt;在棋盤上選擇下一個你想要移動的棋子。&lt;/li&gt;</span></span>
<span class="line"><span>    &lt;/ul&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;p&gt;要隨時退出遊戲，請按 &lt;b&gt;Q&lt;/b&gt;（大寫</span></span>
<span class="line"><span>    Q）或按 &lt;i&gt;Esc&lt;/i&gt;，這樣遊戲會提示你是否想要</span></span>
<span class="line"><span>    放棄比賽。&lt;/p&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;p&gt;如果你比對手更快將所有棋子移出棋盤，你就贏得了比賽。</span></span>
<span class="line"><span>    這同時需要運氣和遊戲策略！&lt;/p&gt;</span></span>
<span class="line"><span>  &lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>此 HTML 文檔演示了利用 HTML 的技術寫作者經常使用的一些塊和內聯元素。塊元素在圍繞文本定義一個矩形。段落和標題就是塊元素，因為它們從文檔的左邊緣延伸到右邊緣。例如，<code>&lt;p&gt;</code> 在段落周圍包含一個不可見的矩形。相比之下，內聯元素的使用則緊跟在它們包圍的文本。如果你在段落中的某些文本上使用 <code>&lt;b&gt;</code>，則只有被 <code>&lt;b&gt;</code> 和 <code>&lt;/b&gt;</code> 包圍的文本會變為粗體。</p><p>你可以將直接樣式應用於此文檔以更改字體、顏色和其他文本樣式，但修改文檔外觀的更有效方法是將樣式表應用於文檔本身。你可以在 <code>&lt;head&gt;</code> 元素中使用其他元數據執行此操作。你可以為樣式表引用文件，但在這個例子中，我使用 <code>&lt;style&gt;</code> 塊在文檔中定義樣式表。以下是帶有空樣式表的 <code>&lt;head&gt;</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;!DOCTYPE html&gt;</span></span>
<span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>  &lt;head&gt;</span></span>
<span class="line"><span>    &lt;title&gt;簡易 Senet&lt;/title&gt;</span></span>
<span class="line"><span>    &lt;style&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &lt;/style&gt;</span></span>
<span class="line"><span>  &lt;/head&gt;</span></span>
<span class="line"><span>  &lt;body&gt;</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>  &lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><h3 id="定義樣式" tabindex="-1">定義樣式 <a class="header-anchor" href="#定義樣式" aria-label="Permalink to “定義樣式”">​</a></h3><p>由於你剛剛開始學習樣式表，因此這裏先演示一種基本樣式：背景色。我喜歡從背景顏色開始，因為它有助於演示塊和內聯元素。讓我們應用一個有點華麗的樣式表，為所有 <code>&lt;p&gt;</code> 段落設置<em>淺藍色</em>背景顏色，為 <code>&lt;ul&gt;</code> 無序列表設置<em>淺綠色</em>背景。對任何粗體文本使用<em>黃色</em>背景，對任何斜體文本使用<em>粉紅色</em>背景。</p><p>你可以在 HTML 文檔的 <code>&lt;style&gt;</code> 塊中使用樣式來定義這些樣式。樣式表使用與 HTML 文檔不同的標記。樣式語法看起來像 <code>element { style; style; style; ... }</code> 並使用花括號將多種文本樣式組合到一個定義中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;style&gt;</span></span>
<span class="line"><span>p { background-color: lightblue; }</span></span>
<span class="line"><span>ul { background-color: lightgreen; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>b { background-color: yellow; }</span></span>
<span class="line"><span>i { background-color: pink; }</span></span>
<span class="line"><span>    &lt;/style&gt;</span></span></code></pre></div><p>請注意，每個樣式都以分號結尾。</p><p>如果在網頁瀏覽器中查看此 HTML 文檔，你可以看到 <code>&lt;p&gt;</code> 和 <code>&lt;ul&gt;</code> 塊元素如何填充為矩形，而 <code>&lt;b&gt;</code> 和 <code>&lt;i&gt;</code> 內聯元素僅突出顯示粗體和斜體文本。 這種對比色的使用可能看起來不太好看，但我想你可以清楚看到塊和內聯元素：</p><p><img src="https://opensource.com/sites/default/files/2022-08/style-html-1.png" alt="辣眼睛！但是這些顏色確實能幫助我麼更好地看出塊和內聯元素的區別。"></p><h3 id="應用樣式" tabindex="-1">應用樣式 <a class="header-anchor" href="#應用樣式" aria-label="Permalink to “應用樣式”">​</a></h3><p>你可以使用樣式使這個自述文件更易於閲讀。 因為你剛剛開始學習樣式，還是先只用一些簡單的樣式元素：</p><ul><li><code>background-color</code> 設置背景顏色</li><li><code>color</code> 設置文字顏色</li><li><code>font-family</code> 使用不同的文本字體</li><li><code>margin-top</code> 在元素上方添加空間</li><li><code>margin-bottom</code> 在元素下方添加空間</li><li><code>text-align</code> 改變文本的對齊方式，例如靠左、靠右或居中</li></ul><p>讓我們重新開始你的樣式表並將這些新樣式應用到文檔中。首先，在文檔中使用更令人愉悦的字體。如果你的 HTML 文檔沒有指定字體，網絡瀏覽器會為你選擇一種。根據瀏覽器的設置方式，這可能是襯線字體（如我的屏幕截圖中使用的字體）或無襯線字體。襯線字體在每個字母上添加了一個小筆畫，這樣在打印時更容易閲讀。無襯線字體缺少這種額外的筆劃，這使得文本在計算機顯示器上顯得更清晰。常見的襯線字體包括 Garamond 或 Times New Roman。 流行的無襯線字體包括 Roboto 和 Arial。</p><p>例如，要將文檔正文字體設置為 Roboto，你可以使用以下樣式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>body { font-family: Roboto; }</span></span></code></pre></div><p>通過設置字體，你假設查看文檔的人也安裝了該字體。有些字體已經十分常見，以至於它們被認為是事實上的“網頁安全”字體。 這些字體包括 Arial 等無襯線字體和 Times New Roman 等襯線字體。Roboto 是一種較新的字體，可能還無法隨處可用。因此，網頁設計師通常不會只列出一種字體，而是設置一種或多種“備用”字體。你可以通過用逗號分隔來添加這些替代字體。 例如，如果用户的系統上沒有 Roboto 字體，你可以使用以下樣式定義將 Arial 字體用作文本正文：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>body { font-family: Roboto, Arial; }</span></span></code></pre></div><p>所有網絡瀏覽器都定義了默認的襯線和無襯線字體，你可以使用這些名稱來引用它們。用户可以更改他們喜歡用於顯示襯線和無襯線的字體，因此不太可能對每個人都一樣，但在字體列表中使用 <code>serif</code> 或 <code>sans-serif</code> 通常是個好主意。通過添加該字體，至少用户可以大致瞭解你希望 HTML 文檔的呈現方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>body { font-family: Roboto, Arial, sans-serif; }</span></span></code></pre></div><p>如果字體名稱不止一個單詞，則你必須在其兩邊加上引號。HTML 允許你在此處使用單引號或雙引號。 為標題和副標題定義一些襯線字體，包括 Times New Roman：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>h1 { font-family: &quot;Times New Roman&quot;, Garamond, serif; }</span></span>
<span class="line"><span>h2 { font-family: &quot;Times New Roman&quot;, Garamond, serif; }</span></span></code></pre></div><p>請注意，H1 標題和 H2 副標題使用完全相同的字體定義。如果你想避免無謂的打字，可以使用樣式錶快捷方式為 H1 和 22 使用相同的樣式定義：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>h1, h2 { font-family: &quot;Times New Roman&quot;, Garamond, serif; }</span></span></code></pre></div><p>在編寫文檔時，許多技術作者更喜歡將主標題放在頁面的中央。你可以在塊元素（例如 H1 標題）上使用 <code>text-align</code> 來使標題居中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>h1 { text-align: center; }</span></span></code></pre></div><p>為了讓粗體和斜體文本更突出，請將它們置於稍微不同的顏色中。對於某些文檔，我可能會使用深藍表示粗體文本，使用深綠表示斜體文本。這些顏色非常接近黑色，但顏色的細微差別足以吸引讀者的注意力。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b { color: darkblue; }</span></span>
<span class="line"><span>i { color: darkgreen; }</span></span></code></pre></div><p>最後，我更喜歡在我的列表元素周圍添加額外的間距，以使它們更易於閲讀。如果每個列表項只有幾個詞，額外的空間可能無關緊要。但是我的示例文本中的中間項很長，可以換到第二行。 額外的空間有助於讀者更清楚地看到此列表中的每個項目。 你可以使用邊距樣式在塊元素上方和下方添加空間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>li { margin-top: 10px; margin-bottom: 10px; }</span></span></code></pre></div><p>這種樣式定義了一個距離，此處我將其指定為每個列表元素上方和下方的 10px（十個<em>像素</em>）。 你可以使用多種不同的距離度量。十像素實際上就是屏幕上十個像素的空間，無論是台式機顯示器、筆記本電腦顯示屏，還是手機或平板電腦屏幕。</p><p>假設你真的只是想在列表元素之間添加一個額外的空行，你也可以使用 <code>em</code> 來測量。<code>em</code> 是一箇舊的排版術語，如果你指的是左右間距，它就是大寫 <code>M</code> 的寬度，或者對於垂直間距，就是大寫 <code>M</code> 的高度。所以你可以改用 1em 來寫邊距樣式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>li { margin-top: 1em; margin-bottom: 1em; }</span></span></code></pre></div><p>HTML 文檔中的完整樣式列表如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;!DOCTYPE html&gt;</span></span>
<span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>  &lt;head&gt;</span></span>
<span class="line"><span>    &lt;title&gt;簡易 Senet&lt;/title&gt;</span></span>
<span class="line"><span>    &lt;style&gt;</span></span>
<span class="line"><span>      body { font-family: Roboto, Arial, sans-serif; }</span></span>
<span class="line"><span>      h1, h2 { font-family: &quot;Times New Roman&quot;, Garamond, serif; }</span></span>
<span class="line"><span>      h1 { text-align: center; }</span></span>
<span class="line"><span>      b { color: darkblue; }</span></span>
<span class="line"><span>      i { color: darkgreen; }</span></span>
<span class="line"><span>      li { margin-top: 1em; margin-bottom: 1em; }</span></span>
<span class="line"><span>    &lt;/style&gt;</span></span>
<span class="line"><span>  &lt;/head&gt;</span></span>
<span class="line"><span>  &lt;body&gt;</span></span>
<span class="line"><span>    &lt;h1&gt;簡易 Senet&lt;/h1&gt;</span></span>
<span class="line"><span>    &lt;h2&gt;遊戲玩法&lt;/h2&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;p&gt;遊戲會自動為你“投擲”投擲棒，並在屏幕右下角顯示結果。&lt;/p&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;p&gt;如果“投擲”結果為零，你失去本輪機會。&lt;/p&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;p&gt;輪到你的時候，遊戲會自動選擇</span></span>
<span class="line"><span>    你在棋盤上的第一塊棋子。 你不一定</span></span>
<span class="line"><span>    能夠用這個棋子走棋。所以選擇你的棋子</span></span>
<span class="line"><span>    移動，然後按 &lt;i&gt;Space&lt;/i&gt;（或 &lt;i&gt;Enter&lt;/i&gt;）移動</span></span>
<span class="line"><span>    它。 你可以通過幾種不同的方法進行選擇：&lt;/p&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;ul&gt;</span></span>
<span class="line"><span>      &lt;li&gt;&lt;i&gt;向上&lt;/i&gt;/&lt;i&gt;向下&lt;/i&gt;/&lt;i&gt;向左&lt;/i&gt;/&lt;i&gt;向右&lt;/i&gt; to</span></span>
<span class="line"><span>      朝特定方塊移動。&lt;/li&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>      &lt;li&gt;加號 (&lt;b&gt;+&lt;/b&gt;) 或減號 (&lt;b&gt;-&lt;/b&gt;) 使棋子在棋盤上向“左”或向“右”移動。</span></span>
<span class="line"><span>      請注意，它們會自動遵循棋盤的“倒過來的 S”方向移動。&lt;/li&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>      &lt;li&gt;&lt;em&gt;Tab&lt;/em&gt;在棋盤上選擇下一個你想要移動的棋子。&lt;/li&gt;</span></span>
<span class="line"><span>    &lt;/ul&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;p&gt;要隨時退出遊戲，請按 &lt;b&gt;Q&lt;/b&gt;（大寫</span></span>
<span class="line"><span>    Q）或按 &lt;i&gt;Esc&lt;/i&gt;，這樣遊戲會提示你是否想要</span></span>
<span class="line"><span>    放棄比賽。&lt;/p&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;p&gt;如果你比對手更快將所有棋子移出棋盤，你就贏得了比賽。</span></span>
<span class="line"><span>    這同時需要運氣和遊戲策略！&lt;/p&gt;</span></span>
<span class="line"><span>  &lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>在網頁瀏覽器上查看時，你會看到採用無襯線字體的自述文件，標題和副標題使用襯線字體。 頁面標題居中。粗體和斜體文本使用略有不同的顏色來吸引讀者的注意力而不會分散注意力。 最後，列表項周圍有額外的空間，使每個項目更易於閲讀。</p><p><img src="https://opensource.com/sites/default/files/2022-08/style-html-2.png" alt="通過添加一些樣式，我們使這個自述文件更易於閲讀。"></p>`,38)),a("p",null,[s[14]||(s[14]=n("這是在技術寫作中使用樣式的簡單介紹。掌握了基礎知識後，你可能會對 ",-1)),t(l,{href:"https://developer.mozilla.org/en-US/docs/Web/HTML"},{default:p(()=>[...s[13]||(s[13]=[n("Mozilla 的 HTML 指南",-1)])]),_:1}),s[15]||(s[15]=n(" 感興趣。它包括一些很棒的初學者教程，因此你可以學習如何創建自己的網頁。",-1))]),a("p",null,[s[17]||(s[17]=n("有關 CSS 樣式的更多信息，我推薦 ",-1)),t(l,{href:"https://developer.mozilla.org/en-US/docs/Web/CSS"},{default:p(()=>[...s[16]||(s[16]=[n("Mozilla 的 CSS 指南",-1)])]),_:1}),s[18]||(s[18]=n("。",-1))]),s[36]||(s[36]=a("p",null,[a("em",null,"（題圖： MJ:web internet traffic design）")],-1)),s[37]||(s[37]=a("hr",null,null,-1)),a("p",null,[s[20]||(s[20]=n("via: ",-1)),t(l,{href:"https://opensource.com/article/22/8/css-html-project-documentation"},{default:p(()=>[...s[19]||(s[19]=[n("https://opensource.com/article/22/8/css-html-project-documentation",-1)])]),_:1})]),a("p",null,[s[25]||(s[25]=n("作者：",-1)),t(l,{href:"https://opensource.com/users/jim-hall"},{default:p(()=>[...s[21]||(s[21]=[n("Jim Hall",-1)])]),_:1}),s[26]||(s[26]=n(" 選題：",-1)),t(l,{href:"https://github.com/lkxed"},{default:p(()=>[...s[22]||(s[22]=[n("lkxed",-1)])]),_:1}),s[27]||(s[27]=n(" 譯者：",-1)),t(l,{href:"https://github.com/XiaotingHuang22"},{default:p(()=>[...s[23]||(s[23]=[n("XiaotingHuang22",-1)])]),_:1}),s[28]||(s[28]=n(" 校對：",-1)),t(l,{href:"https://github.com/wxy"},{default:p(()=>[...s[24]||(s[24]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[31]||(s[31]=n("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[29]||(s[29]=[n("LCTT",-1)])]),_:1}),s[32]||(s[32]=n(" 原創編譯，",-1)),t(l,{href:"https://linux.cn/"},{default:p(()=>[...s[30]||(s[30]=[n("Linux中國",-1)])]),_:1}),s[33]||(s[33]=n(" 榮譽推出",-1))])])}con